    function wordsToNumber(text) {
        var units = {
            one:1, two:2, three:3, four:4, five:5, six:6, seven:7,
            eight:8, nine:9, ten:10, eleven:11, twelve:12
        };
        var tens = {
            twenty:20, thirty:30, forty:40, fifty:50,
            sixty:60, seventy:70, eighty:80, ninety:90
        };
        var t = String(text || "").trim().toLowerCase();
        if (/^\d+(?:\.\d+)?$/.test(t)) { return Number(t); }
        var parts = t.split(/\s+/);
        var total = 0;
        var matched = false;
        for (var p = 0; p < parts.length; p++) {
            if (units.hasOwnProperty(parts[p])) { total += units[parts[p]]; matched = true; }
            else if (tens.hasOwnProperty(parts[p])) { total += tens[parts[p]]; matched = true; }
            else if (parts[p] === "hundred") { total *= 100; matched = true; }
        }
        return matched ? total : NaN;
    }

    var osQty = null;
    var osQtyMatch = clean.match(/(?:quantity|qty)\s+([a-z0-9]+(?:\s+[a-z0-9]+)?)/);
