        osDateObj.getFullYear() !== osYear ||
        osDateObj.getMonth() !== osMonth ||
        osDateObj.getDate() !== osDay
    ) {
        sendResponse("I could not understand the production date. Please provide a valid date.");
        msg.samCommand = null; msg.machineCommand = null; msg.backendCommands = [];
        return msg;
    }
    var osDateStr =
        String(osDay).padStart(2, "0") + "/" +
        String(osMonth + 1).padStart(2, "0") + "/" + osYear;

    // ---------- TIME ----------
    var osTimeMatch = clean.match(/(\d{1,2})(?::|\.|\s)(\d{1,2})?\s*(am|pm|a\s*m|p\s*m)?/i);
    if (!osTimeMatch) {
        sendResponse(
            "I could not understand the production time. Please include a time, for example 4:40 PM."
        );
        msg.samCommand = null; msg.machineCommand = null; msg.backendCommands = [];
        return msg;
    }
    var osHour = Number(osTimeMatch[1]);
    var osMinute = osTimeMatch[2] ? Number(osTimeMatch[2]) : 0;
    var osAmpm = (osTimeMatch[3] || "").replace(/\s/g, "").toLowerCase();
    if (!(osTimeMatch[2] !== undefined || osAmpm)) {
        sendResponse(
            "I could not understand the production time. Please include a time, for example 4:40 PM."
        );
        msg.samCommand = null; msg.machineCommand = null; msg.backendCommands = [];
        return msg;
    }
    if (osAmpm === "pm" && osHour !== 12) { osHour += 12; }
    else if (osAmpm === "am" && osHour === 12) { osHour = 0; }
    if (osHour < 0 || osHour > 23 || osMinute < 0 || osMinute > 59) {
        sendResponse("I could not understand the production time. Please provide a valid time.");
        msg.samCommand = null; msg.machineCommand = null; msg.backendCommands = [];
        return msg;
    }
    var osTimeStr =
        String(osHour).padStart(2, "0") + ":" + String(osMinute).padStart(2, "0");

    // ---------- SPEED ----------
    var osSpeedMatch = clean.match(/(\d+(?:\.\d+)?)\s*%/);
    var osSpeed = null;
    if (osSpeedMatch) { osSpeed = Number(osSpeedMatch[1]); }
    if (osSpeed === null || isNaN(osSpeed) || osSpeed <= 0) {
        sendResponse(
            "I could not understand the production speed. Please include a speed percentage, for example 6%."
        );
        msg.samCommand = null; msg.machineCommand = null; msg.backendCommands = [];
        return msg;
    }

    // ---------- BUILD + EMIT ORDER ----------
    var osOrder = {
        item: osItem,
        itemSlno: osSlno,
        quantity: osQty,
        productionSpeed: osSpeed,
        productionDate: osDateStr,
        productionTime: osTimeStr
