    msg.samCommand = true;
    msg.machineCommand = true;
    msg.orderPlaced = true;
    backendCommands.push("PLACE_PRODUCTION_ORDER");
    msg.backendCommands = backendCommands;

    flow.set("SAM_PRODUCTION_STATE", "NORMAL");
    flow.set("SAM_PRODUCTION_ORDER", {});
    flow.set("SAM_itemSelectionMode", false);
    flow.set("SAM_itemSelectionItems", []);
    flow.set("SAM_VOICE_ACTIVE", false);
    flow.set("SAM_VOICE_PAUSED", false);
    msg.stopVoice = true;
    msg.closeItemPopup = true;
    msg.command = "PRODUCTION_ORDER_PLACED";

    return msg;
}


