            "I could not determine the machine status. Please check the machine."
        );

        node.warn(
            "SAM MACHINE STATUS | global.SAM_data.machineStatus unavailable"
        );
    }

    msg.samCommand = null;
    msg.machineCommand = null;
    msg.backendCommands = [];
    msg.stopVoice = false;
    msg.orderPlaced = false;
    msg.suppressResponse = false;

    return msg;
}


// ============================================================
// MACHINE ON
// ============================================================

if (
    clean === "machine on" ||
    clean === "turn machine on" ||
    clean === "switch machine on" ||
    clean === "on machine"
) {

    msg.samCommand = true;

    // PLC command must be sent
    msg.machineCommand = true;

    msg.suppressResponse = true;

    msg.backendCommands = [
        "MACHINE_ON"
    ];

    if (
        state === "WAITING_MACHINE_ON"
    ) {

        flow.set(
            "SAM_PRODUCTION_STATE",
            "WAITING_PLACE_ORDER"
        );

        node.warn(
            "SAM MACHINE ON | Production sequence -> WAITING_PLACE_ORDER"
        );
    }

    else {

        flow.set(
            "SAM_PRODUCTION_STATE",
            state
        );

        node.warn(
            "SAM MACHINE ON | Production state preserved: " +
            state
        );
    }

    node.warn(
        "SAM MACHINE COMMAND | ON | samCommand=true"
    );

    return msg;
}


// ============================================================
// MACHINE OFF
// ============================================================

if (
    clean === "machine off" ||
    clean === "turn machine off" ||
    clean === "switch machine off" ||
    clean === "off machine" ||
    clean === "stop the machine" ||
    clean === "stop machine"
) {

    // PLC needs false
    msg.samCommand = false;

    // Keep machineCommand true so PLC node processes command
    msg.machineCommand = true;

    msg.suppressResponse = true;

    msg.backendCommands = [
        "MACHINE_OFF"
    ];

    flow.set(
        "SAM_PRODUCTION_STATE",
        state
    );

    node.warn(
        "SAM MACHINE COMMAND | OFF | samCommand=false"
    );

    node.warn(
        "SAM MACHINE OFF | Production state preserved: " +
        state
    );

    return msg;
}


// ============================================================
// STOP PRODUCTION ORDER
// ============================================================

if (
    clean === "stop production order" ||
    clean === "stop the production order" ||
    clean === "cancel production order" ||
    clean === "cancel the production"
) {

    flow.set(
        "SAM_PRODUCTION_STATE",
        "NORMAL"
    );

    flow.set(
        "SAM_PRODUCTION_ORDER",
        {}
    );

    flow.set(
        "SAM_itemSelectionMode",
        false
    );

    flow.set(
        "SAM_itemSelectionItems",
        []
    );

    sendResponse(
        "Production order stopped."
    );

    msg.stopVoice = false;
    msg.samCommand = null;
    msg.machineCommand = null;
    msg.backendCommands = [];

    msg.closeItemPopup = true;

    return msg;
}


// ============================================================
// SHOW ITEM LIST - NORMAL CONDITION ONLY
// ============================================================

if (
    state === "NORMAL" &&
    (
        clean === "show item list" ||
        clean === "show items" ||
        clean === "item list" ||
        clean === "show production items"
    )
) {

    // Make sure NORMAL list does not activate
    // production item-selection mode.

    flow.set(
        "SAM_itemSelectionMode",
        false
    );

    flow.set(
        "SAM_itemSelectionItems",
        availableItems
    );

    // Create numbered list for popup

    var normalItemList = [];

    for (
        var ni = 0;
        ni < availableItems.length;
        ni++
    ) {

        var normalItem = availableItems[ni];

        if (
            normalItem &&
            typeof normalItem === "object"
        ) {

            normalItemList.push({
                slno: ni + 1,
                item: String(
                    normalItem.item || ""
                ).trim()
            });
        }

        else {

            normalItemList.push({
                slno: ni + 1,
                item: String(
                    normalItem || ""
                ).trim()
            });
        }
    }

    msg.topic = "SAM_ITEM_LIST";

    msg.payload = {
        show: true,
        title: "This is the item list.",
        instruction: "",
        items: normalItemList
    };

    msg.showItemList = true;
    msg.startItemSelection = false;
    msg.itemSelectionMode = false;

    msg.samCommand = null;
    msg.machineCommand = null;
    msg.backendCommands = [];

    msg.closeItemPopup = false;

    node.warn(
        "SAM ITEM LIST | NORMAL DISPLAY | " +
        JSON.stringify(normalItemList)
    );

    return msg;
}


// ============================================================
// START PRODUCTION ORDER
// ============================================================

if (
    state === "NORMAL" &&
    (
        clean === "start production" ||
        clean === "start production order" ||
        clean === "start the production order" ||
        clean === "heart production" ||
        clean === "heart production order" ||
        clean === "heart the production order"
    )
) {

    order = {};

    flow.set(
        "SAM_PRODUCTION_ORDER",
        order
    );

    flow.set(
        "SAM_PRODUCTION_STATE",
        "WAITING_ITEM"
    );

    // ========================================================
    // START ITEM SELECTION POPUP
    // ========================================================

    flow.set(
        "SAM_itemSelectionMode",
        true
    );

    flow.set(
        "SAM_itemSelectionItems",
        availableItems
    );

    msg.startItemSelection = true;

    msg.itemSelectionMode = true;

    msg.itemSelectionItems =
        availableItems;

    sendResponse(
        "Please select the production item from the list and speak its serial number."
    );

    msg.samCommand = null;
    msg.machineCommand = null;
    msg.backendCommands = [];

    return msg;
}


// ============================================================
// PRODUCTION CONVERSATION
// ============================================================

if (
    state !== "NORMAL"
) {


    // ========================================================
    // SAM PRODUCTION ITEM SELECTION
    // ========================================================

    var itemSelectionMode =
        flow.get("SAM_itemSelectionMode") === true;

    if (itemSelectionMode) {

        var spokenNumber =
            String(msg.payload || "")
                .trim()
                .toLowerCase();

        // ====================================================
        // CONVERT SPOKEN SERIAL NUMBER
        // ====================================================

        var slno = null;

        var speech = spokenNumber
            .replace(/[.,!?]/g, "")
            .trim();

        if (
            /\b(1|one)\b/.test(speech)
        ) {

            slno = 1;
        }

        else if (
            /\b(2|two)\b/.test(speech)
        ) {

            slno = 2;
        }

        else if (
            /\b(3|three)\b/.test(speech)
        ) {

            slno = 3;
        }


        // ====================================================
        // GET ITEM LIST
        // ====================================================

        var itemList =
            flow.get("SAM_itemSelectionItems");

        if (
            !Array.isArray(itemList) ||
            itemList.length === 0
        ) {

            itemList =
                availableItems;
        }


        // ====================================================
        // INVALID SERIAL NUMBER
        // ====================================================

        if (
            slno === null ||
            slno < 1 ||
            slno > itemList.length
        ) {

            node.warn(
                "SAM ITEM SELECTION | Invalid serial number: " +
                spokenNumber
            );

            sendResponse(
                "Please select a valid item number from the list."
            );

            msg.samCommand = null;
            msg.machineCommand = null;
            msg.backendCommands = [];

            return msg;
        }


        // ====================================================
        // SERIAL NUMBER -> ITEM
        // ====================================================

        var selectedEntry =
            itemList[slno - 1];

        var selectedItem = "";

        if (
            selectedEntry &&
            typeof selectedEntry === "object"
        ) {

            selectedItem =
                String(
                    selectedEntry.item || ""
                ).trim();
        }

        else {

            selectedItem =
                String(
                    selectedEntry || ""
                ).trim();
        }


        if (!selectedItem) {

            node.warn(
                "SAM ITEM SELECTION | Item not found: " +
                slno
            );

            sendResponse(
                "That item number is not available."
            );

            msg.samCommand = null;
            msg.machineCommand = null;
            msg.backendCommands = [];

            return msg;
        }


        // ====================================================
        // SAVE SELECTED ITEM + SERIAL NUMBER
        // ====================================================

        order.itemSlno = slno;

        order.item = selectedItem;

        flow.set(
            "SAM_selectedItemSlno",
            slno
        );

        flow.set(
            "SAM_selectedItem",
            selectedItem
        );

        flow.set(
            "SAM_PRODUCTION_ORDER",
            order
        );


        // ====================================================
        // EXIT ITEM SELECTION MODE
        // ====================================================

        flow.set(
            "SAM_itemSelectionMode",
            false
        );

        // CLOSE POPUP
        msg.closeItemPopup = true;


        // ====================================================
        // MOVE TO NEXT PRODUCTION STEP
        // ====================================================

        flow.set(
            "SAM_PRODUCTION_STATE",
            "WAITING_QTY"
        );


        // ====================================================
        // OUTPUT
        // ====================================================

        msg.topic =
            "PRODUCTION_ITEM";

        msg.payload =
            selectedItem;

        msg.itemSlno =
            slno;

        msg.item =
            selectedItem;

        msg.selectedItem =
            selectedItem;

        msg.selectedItemSlno =
            slno;


        node.warn(
            "SAM ITEM SELECTED | " +
            "SLNO = " + slno +
            " | ITEM = " + selectedItem +
            " | NEXT = WAITING_QTY"
        );


        // ====================================================
        // SAM RESPONSE
        // ====================================================

        sendResponse(
            "Item " +
            selectedItem +
            " selected. What quantity should I produce?"
        );

        msg.samCommand = null;
        msg.machineCommand = null;
        msg.backendCommands = [];

        return msg;
    }


    // ========================================================
    // WAITING ITEM FALLBACK
    // ========================================================

    if (
        state === "WAITING_ITEM"
    ) {

        var selectedItemName = null;
        var selectedItemFallbackSlno = null;

        for (
            var i = 0;
            i < availableItems.length;
            i++
        ) {

            var itemName = "";

            if (
                availableItems[i] &&
                typeof availableItems[i] === "object"
            ) {

                itemName =
                    String(
                        availableItems[i].item || ""
                    ).trim();
            }

            else {

                itemName =
                    String(
                        availableItems[i] || ""
                    ).trim();
            }

            var itemLower =
                itemName.toLowerCase();

            if (
                clean === itemLower ||
                clean.indexOf(itemLower) !== -1
            ) {

                selectedItemName =
                    itemName;

                selectedItemFallbackSlno =
                    i + 1;

                break;
            }
        }


        // ----------------------------------------------------
        // INVALID ITEM
        // ----------------------------------------------------

        if (!selectedItemName) {

            sendResponse(
                command +
                " is out of stock, sorry for the inconvenience. Please provide another item."
            );

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_ITEM"
            );
        }


        // ----------------------------------------------------
        // VALID ITEM
        // ----------------------------------------------------

        else {

            order.item =
                selectedItemName;

            order.itemSlno =
                selectedItemFallbackSlno;

            flow.set(
                "SAM_selectedItem",
                selectedItemName
            );

            flow.set(
                "SAM_selectedItemSlno",
                selectedItemFallbackSlno
            );

            flow.set(
                "SAM_PRODUCTION_ORDER",
                order
            );

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_QTY"
            );

            flow.set(
                "SAM_itemSelectionMode",
                false
            );

            msg.closeItemPopup = true;

            msg.itemSlno =
                selectedItemFallbackSlno;

            msg.item =
                selectedItemName;

            sendResponse(
                "Item " +
                selectedItemName +
                " selected. What quantity should I produce?"
            );
        }

        msg.samCommand = null;
        msg.machineCommand = null;
        msg.backendCommands = [];

        return msg;
    }


    // ========================================================
    // WAITING QUANTITY
    // ========================================================

    if (
        state === "WAITING_QTY"
    ) {

        var qty = null;

        var qtyMatch =
            clean.match(
                /(?:quantity|qty|set quantity to|produce)\s*(\d+(?:\.\d+)?)/
            );

        if (qtyMatch) {

            qty =
                Number(
                    qtyMatch[1]
                );
        }

        else {

            var directQty =
                clean.match(
                    /^\d+(?:\.\d+)?$/
                );

            if (directQty) {

                qty =
                    Number(
                        directQty[0]
                    );
            }
        }

        var numberWords = {

            "one": 1,
            "two": 2,
            "three": 3,
            "four": 4,
            "five": 5,
            "six": 6,
            "seven": 7,
            "eight": 8,
            "nine": 9,
            "ten": 10,
            "twenty": 20,
            "thirty": 30,
            "forty": 40,
            "fifty": 50,
            "hundred": 100
        };

        if (
            qty === null &&
            numberWords.hasOwnProperty(clean)
        ) {

            qty =
                numberWords[clean];
        }

        if (
            qty === null ||
            isNaN(qty) ||
            qty <= 0
        ) {

            sendResponse(
                "I could not understand the quantity. Please say a number, for example 10."
            );
        }

        else {

            order.quantity =
                qty;

            flow.set(
                "SAM_PRODUCTION_ORDER",
                order
            );

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_SPEED"
            );

            // Close any normal popup before next data
            msg.closeItemPopup = true;

            sendResponse(
                "Quantity set to " +
                qty +
                " pieces. What production speed % ?"
            );
        }

        msg.samCommand = null;
        msg.machineCommand = null;
        msg.backendCommands = [];

        return msg;
    }


    // ========================================================
    // WAITING SPEED
    // ========================================================

    if (
        state === "WAITING_SPEED"
    ) {

        var speedMatch =
            clean.match(
                /(?:set\s+)?(?:production\s+)?speed(?:\s+to)?\s+(\d+(?:\.\d+)?)/
            );

        if (!speedMatch) {

            speedMatch =
                clean.match(
                    /^(\d+(?:\.\d+)?)$/
                );
        }

        if (!speedMatch) {

            sendResponse(
                "Please provide a valid production speed, for example 1000."
            );

            return msg;
        }

        var productionSpeed =
            Number(
                speedMatch[1]
            );

        if (
            !isFinite(productionSpeed) ||
            productionSpeed <= 0
        ) {

            sendResponse(
                "Please provide a valid production speed greater than zero."
            );

            return msg;
        }

        order.productionSpeed =
            productionSpeed;

        flow.set(
            "SAM_PRODUCTION_ORDER",
            order
        );

        flow.set(
            "SAM_PRODUCTION_STATE",
            "WAITING_DATE"
        );

        msg.closeItemPopup = true;

        sendResponse(
            "Production speed set to " +
            productionSpeed +
            ". What production date?"
        );

        return msg;
    }


    // ========================================================
    // WAITING DATE
    // ========================================================

    if (
        state === "WAITING_DATE"
    ) {

        var months = {

            january: 0,
            february: 1,
            march: 2,
            april: 3,
            may: 4,
            june: 5,
            july: 6,
            august: 7,
            september: 8,
            october: 9,
            november: 10,
            december: 11
        };

        var dateMatch =
            clean.match(
                /(\d{1,2})(?:st|nd|rd|th)?\s+(january|february|march|april|may|june|july|august|september|october|november|december)/
            );

        if (!dateMatch) {

            sendResponse(
                "I could not understand the date. Please say, for example, 26 August or 6 November."
            );

            return msg;
        }

        var day =
            Number(
                dateMatch[1]
            );

        var monthName =
            dateMatch[2];

        var month =
            months[monthName];

        var year =
            new Date().getFullYear();

        var testDate =
            new Date(
                year,
                month,
                day
            );

        if (
            testDate.getFullYear() !== year ||
            testDate.getMonth() !== month ||
            testDate.getDate() !== day
        ) {

            sendResponse(
                "I could not understand the date. Please say a valid date, for example 26 August."
            );

            return msg;
        }

        var dayStr =
            String(day).padStart(2, "0");

        var monthStr =
            String(month + 1).padStart(2, "0");

        order.productionDate =
            dayStr +
            "/" +
            monthStr +
            "/" +
            year;

        order.productionYear =
            year;

        order.productionDay =
            day;

        order.productionMonth =
            month + 1;

        flow.set(
            "SAM_PRODUCTION_ORDER",
            order
        );

        flow.set(
            "SAM_PRODUCTION_STATE",
            "WAITING_TIME"
        );

        msg.closeItemPopup = true;

        sendResponse(
            "Production date set to " +
            order.productionDate +
            ". What production time?"
        );

        return msg;
    }


    // ========================================================
    // WAITING TIME
    // ========================================================

    if (
        state === "WAITING_TIME"
    ) {

        var timeMatch =
            clean.match(
                /(\d{1,2})(?::|\.|\s)(\d{1,2})?\s*(am|pm|a m|p m)?/
            );

        if (!timeMatch) {

            sendResponse(
                "I could not understand the time. Please say, for example, 9 AM or 9:30 AM."
            );

            return msg;
        }

        var hour =
            Number(
                timeMatch[1]
            );

        var minute =
            timeMatch[2]
                ? Number(timeMatch[2])
                : 0;

        var ampm =
            timeMatch[3] || "";

        ampm =
            ampm
                .replace(/\s/g, "")
                .toLowerCase();

        if (
            hour < 1 ||
            hour > 12 ||
            minute < 0 ||
            minute > 59
        ) {

            sendResponse(
                "I could not understand the time. Please say, for example, 9 AM or 9:30 AM."
            );

            return msg;
        }

        if (
            ampm === "pm" &&
            hour !== 12
        ) {

            hour += 12;
        }

        if (
            ampm === "am" &&
            hour === 12
        ) {

            hour = 0;
        }

        var hourStr =
            String(hour).padStart(2, "0");

        var minuteStr =
            String(minute).padStart(2, "0");

        order.productionTime =
            hourStr +
            ":" +
            minuteStr;

        flow.set(
            "SAM_PRODUCTION_ORDER",
            order
        );

        msg.closeItemPopup = true;

        // ====================================================
        // READ LIVE MACHINE STATUS
        // ====================================================

        var productionMachineStatus =
            getLiveMachineStatus();

        // ====================================================
        // MACHINE ON
        // ====================================================

        if (
            productionMachineStatus === true
        ) {

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_PLACE_ORDER"
            );

            sendResponse(
                "The machine is currently ON. Place order or Stop?"
            );
        }

        // ====================================================
        // MACHINE OFF
        // ====================================================

        else {

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_MACHINE_ON"
            );

            sendResponse(
                "Machine is in shutdown mode. Turn the machine ON or Stop?"
            );
        }

        return msg;
    }


    // ========================================================
    // MACHINE OFF -> TURN ON
    // ========================================================

    if (
        state === "WAITING_MACHINE_ON"
    ) {

        if (
            clean === "stop" ||
            clean === "no" ||
            clean === "cancel"
        ) {

            flow.set(
                "SAM_PRODUCTION_STATE",
                "NORMAL"
            );

            flow.set(
                "SAM_PRODUCTION_ORDER",
                {}
            );

            flow.set(
                "SAM_itemSelectionMode",
                false
            );

            msg.closeItemPopup = true;

            sendResponse(
                "Production order stopped."
            );

            return msg;
        }

        if (
            clean === "yes" ||
            clean === "turn it on" ||
            clean === "switch it on" ||
            clean === "machine on" ||
            clean === "turn machine on" ||
            clean === "switch machine on"
        ) {

            msg.samCommand = true;

            msg.machineCommand = true;

            msg.suppressResponse = true;

            backendCommands.push(
                "MACHINE_ON"
            );

            msg.backendCommands =
                backendCommands;

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_PLACE_ORDER"
            );

            node.warn(
                "SAM MACHINE ON | WAITING_MACHINE_ON -> WAITING_PLACE_ORDER"
            );

        }

        else {

            sendResponse(
                "Please say Turn the machine ON or Stop."
            );
        }

        return msg;
    }


    // ========================================================
    // WAITING PLACE ORDER
    // ========================================================

    if (
        state === "WAITING_PLACE_ORDER"
    ) {

        // ----------------------------------------------------
        // STOP
        // ----------------------------------------------------

        if (
            clean === "stop" ||
            clean === "no" ||
            clean === "cancel" ||
            clean === "stop order"
        ) {

            flow.set(
                "SAM_PRODUCTION_STATE",
                "NORMAL"
            );

            flow.set(
                "SAM_PRODUCTION_ORDER",
                {}
            );

            msg.closeItemPopup = true;

            sendResponse(
                "Production order stopped."
            );

            return msg;
        }


        // ----------------------------------------------------
        // PLACE ORDER
        // ----------------------------------------------------

        if (
            clean === "place order" ||
            clean === "place the order" ||
            clean === "confirm order" ||
            clean === "confirm" ||
            clean === "yes"
        ) {

            let itemForOrder =
                order.item || "";

            let itemSlnoForOrder =
                order.itemSlno || "";

            let qtyForOrder =
                order.quantity || "";

            let speedForOrder =
                order.productionSpeed || "";

            let dateForOrder =
                order.productionDate || "";

            let timeForOrder =
                order.productionTime || "";


            sendResponse(
                "Placing the production order for SlNo. " +
                itemSlnoForOrder +
                " item " +
                itemForOrder +
                ", Quantity " +
                qtyForOrder +
                ", at speed " +
                speedForOrder +
                " % on " +
                dateForOrder +
                " at " +
                timeForOrder +
                "."
            );


            msg.samCommand = true;

            msg.machineCommand = true;

            msg.orderPlaced = true;

            backendCommands.push(
                "PLACE_PRODUCTION_ORDER"
            );

            msg.backendCommands =
                backendCommands;


            flow.set(
                "SAM_PRODUCTION_STATE",
                "NORMAL"
            );

            flow.set(
                "SAM_PRODUCTION_ORDER",
                {}
            );

            flow.set(
                "SAM_itemSelectionMode",
                false
            );

            flow.set(
                "SAM_itemSelectionItems",
                []
            );

            // COMPLETE VOICE STOP

            flow.set(
                "SAM_VOICE_ACTIVE",
                false
            );

            flow.set(
                "SAM_VOICE_PAUSED",
                false
            );

            msg.stopVoice = true;

            msg.closeItemPopup = true;

            msg.command =
                "PRODUCTION_ORDER_PLACED";

        }

        else {

            sendResponse(
                "Please say Place order or Stop."
            );
        }

        return msg;
    }


    // ========================================================
    // UNKNOWN STATE
    // ========================================================

    flow.set(
        "SAM_PRODUCTION_STATE",
        "NORMAL"
    );

    flow.set(
        "SAM_PRODUCTION_ORDER",
        {}
    );

    flow.set(
        "SAM_itemSelectionMode",
        false
    );

    msg.closeItemPopup = true;

    sendResponse(
        "Production conversation reset. Please say start production order."
    );

    return msg;
}


// ============================================================
// NORMAL CONVERSATION
// ============================================================


// ============================================================
// MY NAME IS
// ============================================================

var nameMatch =
    clean.match(
        /^my name is\s+(.+)$/
    );

if (nameMatch) {

    var newName =
        nameMatch[1]
            .replace(
                /\b(please|sam)\b/gi,
                ""
            )
            .trim();

    if (newName) {

        userName =
            newName
                .split(" ")
                .map(
                    function(word) {

                        return (
                            word.charAt(0).toUpperCase() +
                            word.slice(1)
                        );
                    }
                )
                .join(" ");

        flow.set(
            "SAM_userName",
            userName
        );

        sendResponse(
            "Hello " +
            userName +
            ". I will remember your name."
        );

    }

    else {

        sendResponse(
