// ============================================================

function normalizeText(text) {

    return String(text || "")
        .toLowerCase()
        .replace(/[!?.,:;]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
}


// ============================================================
// CHECK SAM TTS ECHO
// ============================================================

var incomingNormalized =
    normalizeText(command);

var isEcho = false;

for (
    var r = 0;
    r < recentResponses.length;
    r++
) {

    var savedResponse =
        normalizeText(recentResponses[r]);

    if (!savedResponse) {
        continue;
    }

    if (
        incomingNormalized === savedResponse
    ) {

        isEcho = true;
        break;
    }

    if (
        incomingNormalized.length >= 6 &&
        savedResponse.indexOf(
            incomingNormalized
        ) !== -1
    ) {

        isEcho = true;
        break;
    }

    if (
        savedResponse.length >= 8 &&
        incomingNormalized.indexOf(
            savedResponse
        ) !== -1
    ) {

        isEcho = true;
        break;
    }
}

// ============================================================
// COMMON SPOKEN NUMBER CONVERTER
// ============================================================
// Supports:
//   1, 2, 5, 6
//   one, two, five, six
//   number 1, number one
//   quantity 5, quantity five
//   qty 6, qty six
//
// This function is used by all numeric voice-entry sections.
// ============================================================

function spokenNumberToValue(text) {

    var value =
        normalizeText(text);

    if (!value) {
        return null;
    }


    // ========================================================
    // REMOVE COMMON NUMBER PREFIXES
    // ========================================================

    value =
        value
            .replace(/^number\s+/, "")
            .replace(/^no\s+/, "")
            .trim();


    // ========================================================
    // DIRECT DIGITS
    // ========================================================

    var digitMatch =
        value.match(
            /^\d+(?:\.\d+)?$/
        );

    if (digitMatch) {

        return Number(
            digitMatch[0]
        );
    }


    // ========================================================
    // SPOKEN NUMBERS
    // ========================================================

    var numberWords = {

        zero: 0,

        one: 1,
        two: 2,
        three: 3,
        four: 4,
        five: 5,
        six: 6,
        seven: 7,
        eight: 8,
        nine: 9,
        ten: 10,

        eleven: 11,
        twelve: 12,
        thirteen: 13,
        fourteen: 14,
        fifteen: 15,
        sixteen: 16,
        seventeen: 17,
        eighteen: 18,
        nineteen: 19,

        twenty: 20,
        thirty: 30,
        forty: 40,
        fifty: 50,
        sixty: 60,
        seventy: 70,
        eighty: 80,
        ninety: 90,

        hundred: 100
    };


    if (
        numberWords.hasOwnProperty(value)
    ) {

        return numberWords[value];
    }


    // ========================================================
    // COMPOUND NUMBERS
    // Example:
    // twenty five
    // thirty six
    // forty five
    // ========================================================

    var compoundMatch =
        value.match(
            /^(twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety)\s+(one|two|three|four|five|six|seven|eight|nine)$/
        );

    if (compoundMatch) {

        var tens =
            numberWords[
            compoundMatch[1]
            ];

        var ones =
            numberWords[
            compoundMatch[2]
            ];

        return tens + ones;
    }


    return null;
}

