// ========================================================
// PRODUCTION ORDER — NATURAL SENTENCE COMMAND POOL
// ========================================================
// Handles:
// "place the order"
// "please place the order"
// "please the order"
// "I want to place an order"
// "can you place the order"
// "schedule production"
// "please schedule production"
// "set production"
// "produce PCB"
// ========================================================

var productionOrderPatterns = [

    // ----------------------------------------------------
    // PLACE ORDER
    // ----------------------------------------------------

    /\bplace\s+(?:the\s+)?(?:production\s+)?order\b/i,

    /\bplease\s+place\s+(?:the\s+)?(?:production\s+)?order\b/i,

    /\bplease\s+the\s+order\b/i,

    /\bcan\s+you\s+place\s+(?:the\s+)?(?:production\s+)?order\b/i,

    /\bcould\s+you\s+place\s+(?:the\s+)?(?:production\s+)?order\b/i,

    /\bkindly\s+place\s+(?:the\s+)?(?:production\s+)?order\b/i,


    // ----------------------------------------------------
    // CREATE ORDER
    // ----------------------------------------------------

    /\bcreate\s+(?:a\s+)?(?:production\s+)?order\b/i,

    /\bplease\s+create\s+(?:a\s+)?(?:production\s+)?order\b/i,

    /\bmake\s+(?:a\s+)?(?:production\s+)?order\b/i,

    /\bplease\s+make\s+(?:a\s+)?(?:production\s+)?order\b/i,


    // ----------------------------------------------------
    // SET PRODUCTION
    // ----------------------------------------------------

    /\bset\s+(?:the\s+)?production\s+order\b/i,

    /\bplease\s+set\s+(?:the\s+)?production\s+order\b/i,

    /\bset\s+(?:the\s+)?production\b/i,

    /\bplease\s+set\s+(?:the\s+)?production\b/i,


    // ----------------------------------------------------
    // SCHEDULE PRODUCTION
    // ----------------------------------------------------

    /\bschedule\s+(?:the\s+)?production\b/i,

    /\bplease\s+schedule\s+(?:the\s+)?production\b/i,

    /\bschedule\s+(?:a\s+)?(?:production\s+)?order\b/i,

    /\bplease\s+schedule\s+(?:a\s+)?(?:production\s+)?order\b/i,


    // ----------------------------------------------------
    // USER REQUEST
    // ----------------------------------------------------

    /\bi\s+want\s+to\s+place\s+(?:a\s+)?(?:production\s+)?order\b/i,

    /\bi\s+want\s+to\s+create\s+(?:a\s+)?(?:production\s+)?order\b/i,

    /\bi\s+want\s+to\s+make\s+(?:a\s+)?(?:production\s+)?order\b/i,

    /\bi\s+need\s+to\s+place\s+(?:a\s+)?(?:production\s+)?order\b/i,

    /\bi\s+would\s+like\s+to\s+place\s+(?:a\s+)?(?:production\s+)?order\b/i,


    // ----------------------------------------------------
    // CAN / COULD / WOULD
    // ----------------------------------------------------

    /\bcan\s+you\s+schedule\s+(?:the\s+)?production\b/i,

    /\bcould\s+you\s+schedule\s+(?:the\s+)?production\b/i,

    /\bwould\s+you\s+schedule\s+(?:the\s+)?production\b/i,

    /\bcan\s+you\s+set\s+(?:the\s+)?production\b/i,

    /\bcould\s+you\s+set\s+(?:the\s+)?production\b/i,


    // ----------------------------------------------------
    // DIRECT PRODUCTION REQUEST
    // ----------------------------------------------------

    /\bproduce\s+\d+/i,

    /\bproduce\s+(?:the\s+)?(?:item\s+)?[a-z]+\b/i,

    /\bstart\s+production\s+of\b/i,

    /\bstart\s+(?:the\s+)?production\s+for\b/i
];


// ========================================================
// CHECK COMPLETE-SENTENCE PRODUCTION INTENT
// ========================================================

var isProductionOrderCommand =
    productionOrderPatterns.some(
        function (pattern) {
            return pattern.test(command);
        }
    );


// ========================================================
// PRODUCTION ORDER INFORMATION CHECK
// ========================================================

var hasItemWord =
    /\bitem\b/i.test(command);

var hasQuantityWord =
    /\bquantity\b|\bqty\b/i.test(command);

var hasScheduleWord =
    /\bschedule\b/i.test(command);

var hasDateWord =
    /\b(?:on|for)\s+\d{1,2}(?:st|nd|rd|th)?\s+(?:of\s+)?(?:january|february|march|april|may|june|july|august|september|october|november|december)\b/i.test(command);

var hasTimeWord =
    /\b(?:at\s+)?\d{1,2}(?::\d{2})?\s*(?:a\s*\.?\s*m\.?|p\s*\.?\s*m\.?)\b/i.test(command);

var hasSpeedWord =
    /\b\d+(?:\.\d+)?\s*(?:percent|%)\s*(?:production\s+)?speed\b/i.test(command);


// ========================================================
// COMPLETE SENTENCE DETECTED
// ========================================================

if (
    isProductionOrderCommand &&
    hasItemWord &&
    hasQuantityWord &&
    hasScheduleWord
) {

    node.warn(
        "SAM DIRECT ORDER | COMPLETE SENTENCE DETECTED | " +
        command
    );


    // ====================================================
    // ITEM
    // ====================================================

    var directItemMatch =
        command.match(
            /\bitem\s+(.+?)(?=\s*,?\s*(?:and\s+)?quantity\b)/i
        );


    // ====================================================
    // QUANTITY
    // ====================================================

    var directQtyMatch =
        command.match(
            /\b(?:quantity|qty)\s*(?:is|of|to)?\s*(\d+(?:\.\d+)?)\b/i
        );


    // ====================================================
    // DATE
    // ====================================================

    var directDateMatch =
        command.match(
            /\b(?:on\s+)?(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?(january|february|march|april|may|june|july|august|september|october|november|december)\b/i
        );


    // ====================================================
    // TIME
    // ====================================================

    var directTimeMatch =
        command.match(
            /\b(?:at\s+)?(\d{1,2})(?::(\d{2}))?\s*(a\s*\.?\s*m\.?|p\s*\.?\s*m\.?)\b/i
        );


    // ====================================================
    // PRODUCTION SPEED
    // ====================================================

    var directSpeedMatch =
        command.match(
            /\b(?:at\s+)?(\d+(?:\.\d+)?)\s*(?:percent|%)\s*(?:production\s+)?speed\b/i
        );


    // ====================================================
    // DEBUG
    // ====================================================

    node.warn(
        "SAM DIRECT ORDER EXTRACTION | " +

        "ITEM=" +
        (
            directItemMatch
                ? directItemMatch[1].trim()
                : "NOT FOUND"
        ) +

        " | QTY=" +
        (
            directQtyMatch
                ? directQtyMatch[1]
                : "NOT FOUND"
        ) +

        " | DATE=" +
        (
            directDateMatch
                ? directDateMatch[1] +
                " " +
                directDateMatch[2]
                : "NOT FOUND"
        ) +

        " | TIME=" +
        (
            directTimeMatch
                ? directTimeMatch[0]
                : "NOT FOUND"
        ) +

        " | SPEED=" +
        (
            directSpeedMatch
                ? directSpeedMatch[1]
                : "NOT FOUND"
        )
    );


    // ====================================================
    // CHECK MISSING INFORMATION
    // ====================================================

    if (
        !directItemMatch ||
        !directQtyMatch ||
        !directDateMatch ||
        !directTimeMatch ||
        !directSpeedMatch
    ) {

        var missingParts = [];

        if (!directItemMatch) {
            missingParts.push("item");
        }

        if (!directQtyMatch) {
            missingParts.push("quantity");
        }

        if (!directDateMatch) {
            missingParts.push("production date");
        }

        if (!directTimeMatch) {
            missingParts.push("production time");
        }

        if (!directSpeedMatch) {
            missingParts.push("production speed");
        }


        node.warn(
            "SAM DIRECT ORDER | INCOMPLETE INFORMATION | " +
            missingParts.join(", ")
        );


        sendResponse(
            "I need the " +
            missingParts.join(", ") +
            "."
        );

        // ====================================================
        // SAVE PARTIALLY COMPLETED ORDER
        // ====================================================

        var partialOrder = {
            item: directItemMatch
                ? directItemMatch[1].trim()
                : null,

            quantity: directQtyMatch
                ? Number(directQtyMatch[1])
                : null,

            productionDate: directDateMatch
                ? directDateMatch[1] + " " + directDateMatch[2]
                : null,

            productionTime: directTimeMatch
                ? directTimeMatch[0]
                : null,

            productionSpeed: null
        };

        // ====================================================
        // SAVE PENDING ORDER
        // ====================================================

        flow.set(
            "SAM_PRODUCTION_ORDER",
            partialOrder
        );

        flow.set(
            "SAM_PENDING_PRODUCTION_ORDER",
            partialOrder
        );

        // ====================================================
        // IMPORTANT
        // WAIT FOR USER TO PROVIDE MISSING INFORMATION
        // ====================================================

        flow.set(
            "SAM_PRODUCTION_STATE",
            "WAITING_MISSING_INFORMATION"
        );

        node.warn(
            "SAM DIRECT ORDER | WAITING FOR MISSING INFORMATION | " +
            JSON.stringify(partialOrder)
        );

        msg.samCommand = null;
        msg.machineCommand = null;
        msg.backendCommands = [];
        msg.orderPlaced = false;

        return msg;
    }


    // ====================================================
    // CLEAN ITEM
    // ====================================================

    var directItem =
        directItemMatch[1]
            .trim()
            .replace(/^for\s+/i, "")
            .replace(/\s+and\s*$/i, "")
            .trim();


    // ====================================================
    // QUANTITY
    // ====================================================

    var directQuantity =
        Number(
            directQtyMatch[1]
        );


    if (
        !isFinite(directQuantity) ||
        directQuantity <= 0
    ) {

        sendResponse(
            "Please provide a valid production quantity."
        );

        return msg;
    }


    // ====================================================
    // DATE
    // ====================================================

    var directDay =
        Number(
            directDateMatch[1]
        );

    var directMonthName =
        directDateMatch[2]
            .toLowerCase();

    var directMonths = {

        january: 1,
        february: 2,
        march: 3,
        april: 4,
        may: 5,
        june: 6,
        july: 7,
        august: 8,
        september: 9,
        october: 10,
        november: 11,
        december: 12
    };

    var directMonth =
        directMonths[
        directMonthName
        ];


    // ====================================================
    // TIME
    // ====================================================

    var directHour =
        Number(
            directTimeMatch[1]
        );

    var directMinute =
        directTimeMatch[2]
            ? Number(
                directTimeMatch[2]
            )
            : 0;

    var directAmPm =
        directTimeMatch[3]
            .replace(/[\s.]/g, "")
            .toLowerCase();


    if (
        directHour < 1 ||
        directHour > 12 ||
        directMinute < 0 ||
        directMinute > 59
    ) {

        sendResponse(
            "I could not understand the production time."
        );

        return msg;
    }


    // ====================================================
    // AM / PM CONVERSION
    // ====================================================

    if (
        directAmPm === "pm" &&
        directHour !== 12
    ) {

        directHour += 12;
    }

    if (
        directAmPm === "am" &&
        directHour === 12
    ) {

        directHour = 0;
    }


    // ====================================================
    // SPEED
    // ====================================================

    var directSpeed =
        Number(
            directSpeedMatch[1]
        );


    if (
        !isFinite(directSpeed) ||
        directSpeed <= 0
    ) {

        sendResponse(
            "Please provide a valid production speed."
        );

        return msg;
    }


    // ====================================================
    // FIND ITEM
    // ====================================================

    var directSelectedItem = null;
    var directSelectedSlno = null;


    var normalizedDirectItem =
        directItem
            .toLowerCase()
            .replace(/[’']/g, "")
            .replace(/\s+/g, " ")
            .trim()
            .replace(/s$/, "");


    for (
        var di = 0;
        di < availableItems.length;
        di++
    ) {

        var directEntry =
            availableItems[di];

        var directItemName = "";


        if (
            directEntry &&
            typeof directEntry === "object"
        ) {

            directItemName =
                String(
                    directEntry.item || ""
                ).trim();

        } else {

            directItemName =
                String(
                    directEntry || ""
                ).trim();
        }


        var normalizedAvailableItem =
            directItemName
                .toLowerCase()
                .replace(/[’']/g, "")
                .replace(/\s+/g, " ")
                .trim()
                .replace(/s$/, "");


        if (
            normalizedAvailableItem ===
            normalizedDirectItem
        ) {

            directSelectedItem =
                directItemName;

            directSelectedSlno =
                di + 1;

            break;
        }
    }


    // ====================================================
    // ITEM NOT FOUND
    // ====================================================

    if (!directSelectedItem) {

        node.warn(
            "SAM DIRECT ORDER | ITEM NOT FOUND | " +
            directItem
        );


        sendResponse(
            "I could not find the production item " +
            directItem +
            "."
        );


        msg.samCommand = null;
        msg.machineCommand = null;
        msg.backendCommands = [];

        return msg;
    }


    // ====================================================
    // VALIDATE DATE
    // ====================================================

    var currentYear =
        new Date().getFullYear();

    var testDirectDate =
        new Date(
            currentYear,
            directMonth - 1,
            directDay
        );


    if (
        testDirectDate.getMonth() !==
        directMonth - 1 ||

        testDirectDate.getDate() !==
        directDay
    ) {

        sendResponse(
            "I could not understand the production date."
        );

        return msg;
    }


    // ====================================================
    // FORMAT DATE
    // ====================================================

    var directDate =
        String(
            directDay
        ).padStart(2, "0") +

        "/" +

        String(
            directMonth
        ).padStart(2, "0") +

        "/" +

        currentYear;


    // ====================================================
    // FORMAT TIME
    // ====================================================

    var directTime =
        String(
            directHour
        ).padStart(2, "0") +

        ":" +

        String(
            directMinute
        ).padStart(2, "0");


    // ====================================================
    // CREATE PENDING ORDER
    // ====================================================

    var pendingDirectOrder = {

        itemSlno:
            directSelectedSlno,

        item:
            directSelectedItem,

        quantity:
            directQuantity,

        productionSpeed:
            directSpeed,

        productionDate:
            directDate,

        productionTime:
            directTime
    };


    // ====================================================
    // STORE PENDING ORDER
    // ====================================================

    flow.set(
        "SAM_PRODUCTION_ORDER",
        pendingDirectOrder
    );

    flow.set(
        "SAM_PENDING_PRODUCTION_ORDER",
        pendingDirectOrder
    );


    // ====================================================
    // WAIT FOR CONFIRMATION
    // ====================================================

    flow.set(
        "SAM_PRODUCTION_STATE",
        "WAITING_PLACE_ORDER"
    );


    // ====================================================
    // OUTPUT VALUES
    // ====================================================

    msg.itemSlno =
        directSelectedSlno;

    msg.item =
        directSelectedItem;

    msg.quantity =
        directQuantity;

    msg.productionSpeed =
        directSpeed;

    msg.productionDate =
        directDate;

    msg.productionTime =
        directTime;

    msg.productionOrderPending =
        true;


    // ====================================================
    // DISPLAY TIME
    // ====================================================

    var displayHour =
        directHour === 0
            ? 12
            : directHour > 12
                ? directHour - 12
                : directHour;

    var displayMinute =
        directMinute > 0
            ? ":" +
            String(
                directMinute
            ).padStart(2, "0")
            : "";

    var displayAmPm =
        directAmPm === "am"
            ? "AM"
            : "PM";


    // ====================================================
    // CONFIRMATION RESPONSE
    // ====================================================

    sendResponse(

        "OK, setting the production. " +

        "Machine will start on " +

        directDay +

        " " +

        directMonthName +

        " at " +

        displayHour +

        displayMinute +

        " " +

        displayAmPm +

        " and " +

        directQuantity +

        " pieces of " +

        directSelectedItem +

        " will be produced at " +

        directSpeed +

        " percent production speed. " +

        "Say confirm."
    );


    // ====================================================
    // DO NOT EXECUTE YET
    // ====================================================

    msg.samCommand =
        null;

    msg.machineCommand =
        null;

    msg.backendCommands =
        [];

    msg.orderPlaced =
        false;


    // ====================================================
    // DEBUG
    // ====================================================

    node.warn(
        "SAM DIRECT ORDER | PENDING CONFIRMATION | " +
        JSON.stringify(
            pendingDirectOrder
        )
    );


    return msg;
}


// ========================================================
// END DIRECT PRODUCTION ORDER
// ========================================================




// ============================================================
// PRODUCTION ORDER — MISSING INFORMATION CONTINUATION
// ============================================================
// Example:
//
// SAM: "I need the production speed."
//
// User: "speed 10"
//
// This block completes the previously stored order.
// ============================================================

let pendingOrder =
    flow.get("SAM_PRODUCTION_ORDER");


// ============================================================
// ONLY RUN IF A PRODUCTION ORDER IS PENDING
// ============================================================

if (
    pendingOrder &&
    flow.get("SAM_PRODUCTION_STATE") ===
    "WAITING_MISSING_INFORMATION"
) {

    let continuation =
        String(command || "")
            .trim()
            .toLowerCase();


    // ========================================================
    // MISSING SPEED
    // ========================================================

    if (
        /\bspeed\b/i.test(continuation) ||
        /\bproduction\s+speed\b/i.test(continuation) ||
        /^\d+(?:\.\d+)?\s*(?:percent|%)?$/i.test(continuation)
    ) {

        let speedMatch =
            continuation.match(
                /\b(?:production\s+)?speed\s*(?:is|of|at|to)?\s*(\d+(?:\.\d+)?)\s*(?:percent|%)?/i
            );


        // Also support:
        // "10"
        // "10 percent"
        // "10%"

        if (!speedMatch) {

            speedMatch =
                continuation.match(
                    /^(\d+(?:\.\d+)?)\s*(?:percent|%)?$/i
                );
        }


        if (speedMatch) {

            let newSpeed =
                Number(
                    speedMatch[1]
                );


            if (
                isFinite(newSpeed) &&
                newSpeed > 0 &&
                newSpeed <= 100
            ) {

                // ============================================
                // UPDATE PENDING ORDER
                // ============================================

                pendingOrder.productionSpeed =
                    newSpeed;


                flow.set(
                    "SAM_PRODUCTION_ORDER",
                    pendingOrder
                );

                flow.set(
                    "SAM_PENDING_PRODUCTION_ORDER",
                    pendingOrder
                );


                // ============================================
                // ORDER IS NOW COMPLETE
                // ============================================

                flow.set(
                    "SAM_PRODUCTION_STATE",
                    "WAITING_PLACE_ORDER"
                );


                // ============================================
                // GET EXISTING ORDER VALUES
                // ============================================

                let item =
                    pendingOrder.item;

                let quantity =
                    pendingOrder.quantity;

                let productionDate =
                    pendingOrder.productionDate;

                let productionTime =
                    pendingOrder.productionTime;


                // ============================================
                // CONVERT DATE FOR DISPLAY
                // ============================================

                let dateParts =
                    String(
                        productionDate
                    ).split("/");

                let displayDate =
                    dateParts.length === 3
                        ? Number(dateParts[0]) +
                        " " +
                        [
                            "",
                            "January",
                            "February",
                            "March",
                            "April",
                            "May",
                            "June",
                            "July",
                            "August",
                            "September",
                            "October",
                            "November",
                            "December"
                        ][
                        Number(dateParts[1])
                        ]
                        : productionDate;


                // ============================================
                // CONVERT TIME FOR DISPLAY
                // ============================================

                let timeParts =
                    String(
                        productionTime
                    ).split(":");

                let displayHour =
                    Number(
                        timeParts[0]
                    );

                let displayMinute =
                    Number(
                        timeParts[1] || 0
                    );

                let displayAmPm =
                    displayHour >= 12
                        ? "PM"
                        : "AM";


                if (
                    displayHour === 0
                ) {

                    displayHour = 12;

                } else if (
                    displayHour > 12
                ) {

                    displayHour -= 12;
                }


                let displayTime =
                    displayHour +
                    (
                        displayMinute > 0
                            ? ":" +
                            String(
                                displayMinute
                            ).padStart(2, "0")
                            : ""
                    ) +
                    " " +
                    displayAmPm;


                // ============================================
                // STORE OUTPUT VALUES
                // ============================================

                msg.itemSlno =
                    pendingOrder.itemSlno;

                msg.item =
                    item;

                msg.quantity =
                    quantity;

                msg.productionSpeed =
                    newSpeed;

                msg.productionDate =
                    productionDate;

                msg.productionTime =
                    productionTime;

                msg.productionOrderPending =
                    true;


                // ============================================
                // CONFIRMATION RESPONSE
                // ============================================

                sendResponse(

                    "OK, setting the production. " +

                    "Machine will start on " +

                    displayDate +

                    " at " +

                    displayTime +

                    " and " +

                    quantity +

                    " pieces of " +

                    item +

                    " will be produced at " +

                    newSpeed +

                    " percent production speed. " +

                    "Say confirm."
                );


                // ============================================
                // DO NOT EXECUTE YET
                // ============================================

                msg.samCommand =
                    null;

                msg.machineCommand =
                    null;

                msg.backendCommands =
                    [];

                msg.orderPlaced =
                    false;


                node.warn(
                    "SAM PRODUCTION CONTINUATION | " +
                    "SPEED=" +
                    newSpeed +
                    " | PENDING CONFIRMATION"
                );


                return msg;
            }
        }


        // ================================================
        // INVALID SPEED
        // ================================================

        sendResponse(
            "Please provide a production speed between 1 and 100 percent."
        );

        return msg;
    }
}

// ============================================================
// START PRODUCTION ORDER
// ============================================================

if (
    state === "NORMAL" &&
    (
        clean === "start production" ||
        clean === "start production order" ||
        clean === "start the production order" ||
        clean === "heart production" ||
        clean === "heart production order" ||
        clean === "heart the production order"
    )
) {

    order = {};

    flow.set(
        "SAM_PRODUCTION_ORDER",
        order
    );

    flow.set(
        "SAM_PRODUCTION_STATE",
        "WAITING_ITEM"
    );

    // ========================================================
    // START ITEM SELECTION POPUP
    // ========================================================

    flow.set(
        "SAM_itemSelectionMode",
        true
    );

    flow.set(
        "SAM_itemSelectionItems",
        availableItems
    );

    msg.startItemSelection = true;

    msg.itemSelectionMode = true;

    msg.itemSelectionItems =
        availableItems;

    sendResponse(
        "Please select the production item from the list and speak its serial number."
    );

    msg.samCommand = null;
    msg.machineCommand = null;
    msg.backendCommands = [];

    return msg;
}


// ============================================================
// PRODUCTION CONVERSATION
// ============================================================

if (
    state !== "NORMAL"
) {


    // ========================================================
    // SAM PRODUCTION ITEM SELECTION
    // ========================================================

    var itemSelectionMode =
        flow.get("SAM_itemSelectionMode") === true;

    if (itemSelectionMode) {

        var spokenNumber =
            String(msg.payload || "")
                .trim()
                .toLowerCase();
        // ====================================================
        // CONVERT SPOKEN SERIAL NUMBER
        // ====================================================
        // Supports:
        //   1
        //   one
        //   number 1
        //   number one
        //   5
        //   five
        //   6
        //   six
        //
        // The available item list determines whether the number
        // is actually valid.
        // ====================================================

        var slno = null;

        var speech =
            spokenNumber.trim();


        var spokenSlno =
            spokenNumberToValue(
                speech
            );


        if (
            spokenSlno !== null &&
            Number.isInteger(spokenSlno)
        ) {

            slno =
                spokenSlno;
        }

        // ====================================================
        // GET ITEM LIST
        // ====================================================

        var itemList =
            flow.get("SAM_itemSelectionItems");

        if (
            !Array.isArray(itemList) ||
            itemList.length === 0
        ) {

            itemList =
                availableItems;
        }


        // ====================================================
        // INVALID SERIAL NUMBER
        // ====================================================

        if (
            slno === null ||
            slno < 1 ||
            slno > itemList.length
        ) {

            node.warn(
                "SAM ITEM SELECTION | Invalid serial number: " +
                spokenNumber
            );

            sendResponse(
                "Please select a valid item number from the list."
            );

            msg.samCommand = null;
            msg.machineCommand = null;
            msg.backendCommands = [];

            return msg;
        }


        // ====================================================
        // SERIAL NUMBER -> ITEM
        // ====================================================

        var selectedEntry =
            itemList[slno - 1];

        var selectedItem = "";

        if (
            selectedEntry &&
            typeof selectedEntry === "object"
        ) {

            selectedItem =
                String(
                    selectedEntry.item || ""
                ).trim();
        }

        else {

            selectedItem =
                String(
                    selectedEntry || ""
                ).trim();
        }


        if (!selectedItem) {

            node.warn(
                "SAM ITEM SELECTION | Item not found: " +
                slno
            );

            sendResponse(
                "That item number is not available."
            );

            msg.samCommand = null;
            msg.machineCommand = null;
            msg.backendCommands = [];

            return msg;
        }


        // ====================================================
        // SAVE SELECTED ITEM + SERIAL NUMBER
        // ====================================================

        order.itemSlno = slno;

        order.item = selectedItem;

        flow.set(
            "SAM_selectedItemSlno",
            slno
        );

        flow.set(
            "SAM_selectedItem",
            selectedItem
        );

        flow.set(
            "SAM_PRODUCTION_ORDER",
            order
        );


        // ====================================================
        // EXIT ITEM SELECTION MODE
        // ====================================================

        flow.set(
            "SAM_itemSelectionMode",
            false
        );

        // CLOSE POPUP
        msg.closeItemPopup = true;


        // ====================================================
        // MOVE TO NEXT PRODUCTION STEP
        // ====================================================

        flow.set(
            "SAM_PRODUCTION_STATE",
            "WAITING_QTY"
        );


        // ====================================================
        // OUTPUT
        // ====================================================

        msg.topic =
            "PRODUCTION_ITEM";

        msg.payload =
            selectedItem;

        msg.itemSlno =
            slno;

        msg.item =
            selectedItem;

        msg.selectedItem =
            selectedItem;

        msg.selectedItemSlno =
            slno;


        node.warn(
            "SAM ITEM SELECTED | " +
            "SLNO = " + slno +
            " | ITEM = " + selectedItem +
            " | NEXT = WAITING_QTY"
        );


        // ====================================================
        // SAM RESPONSE
        // ====================================================

        sendResponse(
            "Item " +
            selectedItem +
            " selected. What quantity should I produce?"
        );

        msg.samCommand = null;
        msg.machineCommand = null;
        msg.backendCommands = [];

        return msg;
    }


    // ========================================================
    // WAITING ITEM FALLBACK
    // ========================================================

    if (
        state === "WAITING_ITEM"
    ) {

        var selectedItemName = null;
        var selectedItemFallbackSlno = null;

        for (
            var i = 0;
            i < availableItems.length;
            i++
        ) {

            var itemName = "";

            if (
                availableItems[i] &&
                typeof availableItems[i] === "object"
            ) {

                itemName =
                    String(
                        availableItems[i].item || ""
                    ).trim();
            }

            else {

                itemName =
                    String(
                        availableItems[i] || ""
                    ).trim();
            }

            var itemLower =
                itemName.toLowerCase();

            if (
                clean === itemLower ||
                clean.indexOf(itemLower) !== -1
            ) {

                selectedItemName =
                    itemName;

                selectedItemFallbackSlno =
                    i + 1;

                break;
            }
        }


        // ----------------------------------------------------
        // INVALID ITEM
        // ----------------------------------------------------

        if (!selectedItemName) {

            sendResponse(
                command +
                " is out of stock, sorry for the inconvenience. Please provide another item."
            );

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_ITEM"
            );
        }


        // ----------------------------------------------------
        // VALID ITEM
        // ----------------------------------------------------

        else {

            order.item =
                selectedItemName;

            order.itemSlno =
                selectedItemFallbackSlno;

            flow.set(
                "SAM_selectedItem",
                selectedItemName
            );

            flow.set(
                "SAM_selectedItemSlno",
                selectedItemFallbackSlno
            );

            flow.set(
                "SAM_PRODUCTION_ORDER",
                order
            );

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_QTY"
            );

            flow.set(
                "SAM_itemSelectionMode",
                false
            );

            msg.closeItemPopup = true;

            msg.itemSlno =
                selectedItemFallbackSlno;

            msg.item =
                selectedItemName;

            sendResponse(
                "Item " +
                selectedItemName +
                " selected. What quantity should I produce?"
            );
        }

        msg.samCommand = null;
        msg.machineCommand = null;
        msg.backendCommands = [];

        return msg;
    }


    // ========================================================
    // WAITING QUANTITY
    // ========================================================

    if (
        state === "WAITING_QTY"
    ) {

        var qty = null;

        // ========================================================
        // QUANTITY INPUT
        // ========================================================

        var quantityInput =
            clean
                .replace(
                    /\b(quantity|qty|set|to|produce)\b/g,
                    " "
                )
                .replace(
                    /\s+/g,
                    " "
                )
                .trim();


        // ========================================================
        // TRY COMMON SPOKEN NUMBER CONVERTER
        // ========================================================

        qty =
            spokenNumberToValue(
                quantityInput
            );


        // ========================================================
        // FALLBACK: FIND DIGIT INSIDE SENTENCE
        // ========================================================

        if (
            qty === null
        ) {

            var quantityDigitMatch =
                clean.match(
                    /\b(\d+(?:\.\d+)?)\b/
                );

            if (
                quantityDigitMatch
            ) {

                qty =
                    Number(
                        quantityDigitMatch[1]
                    );
            }
        }


        // ========================================================
        // FALLBACK: FIND SPOKEN NUMBER INSIDE SENTENCE
        // ========================================================

        if (
            qty === null
        ) {

            var quantityWordMatch =
                clean.match(
                    /\b(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety)\b/
                );

            if (
                quantityWordMatch
            ) {

                qty =
                    spokenNumberToValue(
                        quantityWordMatch[1]
                    );
            }
        }

        if (
            qty === null ||
            isNaN(qty) ||
            qty <= 0
        ) {

            sendResponse(
                "I could not understand the quantity. Please say a number, for example 10."
            );
        }

        else {

            order.quantity =
                qty;

            flow.set(
                "SAM_PRODUCTION_ORDER",
                order
            );

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_SPEED"
            );

            // Close any normal popup before next data
            msg.closeItemPopup = true;

            sendResponse(
                "Quantity set to " +
                qty +
                " pieces. What production speed % ?"
            );
        }

        msg.samCommand = null;
        msg.machineCommand = null;
        msg.backendCommands = [];

        return msg;
    }


    // ========================================================
    // WAITING SPEED
    // ========================================================

    if (
        state === "WAITING_SPEED"
    ) {

        var speedMatch =
            clean.match(
                /(?:set\s+)?(?:production\s+)?speed(?:\s+to)?\s+(\d+(?:\.\d+)?)/
            );

        if (!speedMatch) {

            speedMatch =
                clean.match(
                    /^(\d+(?:\.\d+)?)$/
                );
        }

        if (!speedMatch) {

            sendResponse(
                "Please provide a valid production speed, for example 1000."
            );

            return msg;
        }

        var productionSpeed =
            Number(
                speedMatch[1]
            );

        if (
            !isFinite(productionSpeed) ||
            productionSpeed <= 0
        ) {

            sendResponse(
                "Please provide a valid production speed greater than zero."
            );

            return msg;
        }

        order.productionSpeed =
            productionSpeed;

        flow.set(
            "SAM_PRODUCTION_ORDER",
            order
        );

        flow.set(
            "SAM_PRODUCTION_STATE",
            "WAITING_DATE"
        );

        msg.closeItemPopup = true;

        sendResponse(
            "Production speed set to " +
            productionSpeed +
            ". What production date?"
        );

        return msg;
    }


    // ========================================================
    // WAITING DATE
    // ========================================================

    if (
        state === "WAITING_DATE"
    ) {

        var months = {

            january: 0,
            february: 1,
            march: 2,
            april: 3,
            may: 4,
            june: 5,
            july: 6,
            august: 7,
            september: 8,
            october: 9,
            november: 10,
            december: 11
        };

        var dateMatch =
            clean.match(
                /(\d{1,2})(?:st|nd|rd|th)?\s+(january|february|march|april|may|june|july|august|september|october|november|december)/
            );

        if (!dateMatch) {

            sendResponse(
                "I could not understand the date. Please say, for example, 26 August or 6 November."
            );

            return msg;
        }

        var day =
            Number(
                dateMatch[1]
            );

        var monthName =
            dateMatch[2];

        var month =
            months[monthName];

        var year =
            new Date().getFullYear();

        var testDate =
            new Date(
                year,
                month,
                day
            );

        if (
            testDate.getFullYear() !== year ||
            testDate.getMonth() !== month ||
            testDate.getDate() !== day
        ) {

            sendResponse(
                "I could not understand the date. Please say a valid date, for example 26 August."
            );

            return msg;
        }

        var dayStr =
            String(day).padStart(2, "0");

        var monthStr =
            String(month + 1).padStart(2, "0");

        order.productionDate =
            dayStr +
            "/" +
            monthStr +
            "/" +
            year;

        order.productionYear =
            year;

        order.productionDay =
            day;

        order.productionMonth =
            month + 1;

        flow.set(
            "SAM_PRODUCTION_ORDER",
            order
        );

        flow.set(
            "SAM_PRODUCTION_STATE",
            "WAITING_TIME"
        );

        msg.closeItemPopup = true;

        sendResponse(
            "Production date set to " +
            order.productionDate +
            ". What production time?"
        );

        return msg;
    }


    // ========================================================
    // WAITING TIME
    // ========================================================

    if (
        state === "WAITING_TIME"
    ) {

        var timeMatch =
            clean.match(
                /(\d{1,2})(?::|\.|\s)(\d{1,2})?\s*(am|pm|a m|p m)?/
            );

        if (!timeMatch) {

            sendResponse(
                "I could not understand the time. Please say, for example, 9 AM or 9:30 AM."
            );

            return msg;
        }

        var hour =
            Number(
                timeMatch[1]
            );

        var minute =
            timeMatch[2]
                ? Number(timeMatch[2])
                : 0;

        var ampm =
            timeMatch[3] || "";

        ampm =
            ampm
                .replace(/\s/g, "")
                .toLowerCase();

        if (
            hour < 1 ||
            hour > 12 ||
            minute < 0 ||
            minute > 59
        ) {

            sendResponse(
                "I could not understand the time. Please say, for example, 9 AM or 9:30 AM."
            );

            return msg;
        }

        if (
            ampm === "pm" &&
            hour !== 12
        ) {

            hour += 12;
        }

        if (
            ampm === "am" &&
            hour === 12
        ) {

            hour = 0;
        }

        var hourStr =
            String(hour).padStart(2, "0");

        var minuteStr =
            String(minute).padStart(2, "0");

        order.productionTime =
            hourStr +
            ":" +
            minuteStr;

        flow.set(
            "SAM_PRODUCTION_ORDER",
            order
        );

        msg.closeItemPopup = true;

        // ====================================================
        // READ LIVE MACHINE STATUS
        // ====================================================

        var productionMachineStatus =
            getLiveMachineStatus();

        // ====================================================
        // MACHINE ON
        // ====================================================

        if (
            productionMachineStatus === true
        ) {

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_PLACE_ORDER"
            );

            sendResponse(
                "The machine is currently ON. Place order or Stop?"
            );
        }

        // ====================================================
        // MACHINE OFF
        // ====================================================

        else {

            flow.set(
                "SAM_PRODUCTION_STATE",
                "WAITING_MACHINE_ON"
            );

            sendResponse(
                "Machine is in shutdown mode. Turn the machine ON or Stop?"
            );
        }

        return msg;
    }


    // ========================================================
    // MACHINE OFF -> TURN ON
    // ========================================================

    if (
        state === "WAITING_MACHINE_ON"
    ) {

        if (
            clean === "stop" ||
            clean === "no" ||
            clean === "cancel"
        ) {

            flow.set(
                "SAM_PRODUCTION_STATE",
                "NORMAL"
            );

            flow.set(
                "SAM_PRODUCTION_ORDER",
                {}
            );

            flow.set(
                "SAM_itemSelectionMode",
                false
            );

            msg.closeItemPopup = true;

            sendResponse(
                "Production order stopped."
            );

            return msg;
        }

        if (
            clean === "yes" ||
            clean === "turn it on" ||
            clean === "switch it on" ||
            clean === "machine on" ||
            clean === "turn machine on" ||
            clean === "switch machine on"
        ) {

            msg.samCommand = true;

            msg.machineCommand = true;

            msg.suppressResponse = true;

            backendCommands.push(
                "MACHINE_ON"
            );

            msg.backendCommands =
                backendCommands;

            flow.set(
                "SAM_PRODUCTION_STATE",
