    return String(text || "")
        .toLowerCase()
        .replace(/[!?.,:;]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
}

function sendResponse(text) {

    response = text;

    var normalizedResponse =
        normalizeText(text);

    recentResponses.push(
        normalizedResponse
    );

    if (
        recentResponses.length > 8
    ) {

        recentResponses.shift();
    }

    flow.set(
        "SAM_RECENT_RESPONSES",
        recentResponses
    );

    flow.set(
        "SAM_VOICE_PAUSED",
        true
    );

    msg.payload = response;

    msg.userName = userName;

    msg.samResponse = response;

    msg.pauseVoice = true;

    return msg;
}


// ============================================================
// HELPER
// READ LIVE MACHINE STATUS
// ============================================================

function getLiveMachineStatus() {

    var samData =
        global.get("SAM_data");

    if (
        samData &&
        typeof samData.machineStatus === "boolean"
    ) {

        return samData.machineStatus;
    }

    return null;
}
// ============================================================
// SHOW ITEM LIST - NORMAL CONDITION ONLY
// ============================================================

if (
    state === "NORMAL" &&
    (
        clean === "show item list" ||
        clean === "show items" ||
        clean === "item list" ||
        clean === "show production items"
    )
) {

    // Make sure NORMAL list does not activate
    // production item-selection mode.

    flow.set(
        "SAM_itemSelectionMode",
        false
    );

    flow.set(
        "SAM_itemSelectionItems",
        availableItems
    );

    // Create numbered list for popup

    var normalItemList = [];

    for (
        var i = 0;
        i < availableItems.length;
        i++
    ) {

        var rawItem = availableItems[i];

        var itemName = "";

        if (typeof rawItem === "string") {
            itemName = rawItem;
        } else if (rawItem && typeof rawItem.item === "string") {
            itemName = rawItem.item;
        } else if (rawItem && typeof rawItem.name === "string") {
            itemName = rawItem.name;
        } else {
            itemName = String(rawItem || "");
        }

        itemName = String(itemName).trim();

        if (!itemName) {
            continue;
        }

        normalItemList.push({
            slno: i + 1,
            item: itemName
        });
    }

    msg.payload = {
        show: true,
        title: "Available Items",
        instruction: "This is the item list.",
        items: normalItemList
    };

    msg.showItemList = true;
    msg.startItemSelection = false;
    msg.itemSelectionMode = false;

    msg.samCommand = null;
    msg.machineCommand = null;
    msg.backendCommands = [];

    msg.closeItemPopup = false;

    node.warn(
        "SAM ITEM LIST | NORMAL DISPLAY | " +
        JSON.stringify(normalItemList)
    );

    return [msg, null];
}


// ============================================================
// START PRODUCTION ORDER
// ============================================================

if (
    state === "NORMAL" &&
    (
        clean === "start production" ||
        clean === "start production order" ||
        clean === "start the production order" ||
        clean === "heart production" ||
        clean === "heart production order" ||
        clean === "heart the production order"
    )
) {

    order = {};

    flow.set(
        "SAM_PRODUCTION_ORDER",
        order
    );

    flow.set(
        "SAM_PRODUCTION_STATE",
        "WAITING_ITEM"
    );

    // ========================================================
    // START ITEM SELECTION POPUP
    // ========================================================

    flow.set(
        "SAM_itemSelectionMode",
        true
    );

    flow.set(
        "SAM_itemSelectionItems",
        availableItems
    );

    msg.startItemSelection = true;

    msg.itemSelectionMode = true;

    msg.itemSelectionItems =
        availableItems;

    sendResponse(
        "Please select the production item from the list and speak its serial number."
    );

    msg.samCommand = null;
    msg.machineCommand = null;
    msg.backendCommands = [];

    return [msg, null];
}

// ============================================================
// FSM ENTRY PASS-THROUGH (Phase 3)
// No early-return matched -> forward to next module (SAM Parser)
// ============================================================
return [null, msg];

// ============================================================
// SAM PARSER - COMPLETE PRODUCTION ORDER CONVERSATION
// MACHINE CONTROL + LIVE MACHINE STATUS
// WITH TTS PAUSE + ECHO PROTECTION
// ============================================================


// ============================================================
// INPUT
// ============================================================

var command = String(msg.payload || "").trim();

if (!command) {
    return null;
}


// ============================================================
// CLEAN COMMAND
// ============================================================

var clean = command
    .toLowerCase()
    .replace(/[!?.,:;]/g, " ")
    .replace(/\s+/g, " ")
    .trim();


// ============================================================
// VARIABLES
// ============================================================

var response = "";

var userName =
    flow.get("SAM_userName") || "";


// ============================================================
// AVAILABLE ITEMS
// ============================================================

var availableItems =
    flow.get("availableItems");

if (
    !Array.isArray(availableItems) ||
    availableItems.length === 0
) {

    availableItems = [
        "PCB",
        "Solid Plate",
        "Round Plate"
    ];
}


var numberWordsStr =
    "zero|one|two|three|four|five|six|seven|eight|nine|ten|" +
    "eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|" +
    "eighteen|nineteen|twenty";

var QUANTITY_BYPASS_REGEX =
    new RegExp("^(quantity\\s+)?(\\d+|" + numberWordsStr + ")$", "i");

var isQuantityBypass =
    QUANTITY_BYPASS_REGEX.test(clean);
// ============================================================
// PRODUCTION STATE
// ============================================================

var state =
    flow.get("SAM_PRODUCTION_STATE") || "NORMAL";


// ============================================================
// PRODUCTION ORDER
// ============================================================

var order =
    flow.get("SAM_PRODUCTION_ORDER") || {};


// ============================================================
// OUTPUT DEFAULTS
// ============================================================

var backendCommands = [];

msg.samCommand = null;
msg.machineCommand = null;
msg.backendCommands = [];
msg.stopVoice = false;
msg.orderPlaced = false;
msg.pauseVoice = false;
msg.suppressResponse = false;
msg.closeItemPopup = false;


// ============================================================
// TTS ECHO PROTECTION
// ============================================================

var recentResponses =
    flow.get("SAM_RECENT_RESPONSES") || [];

if (!Array.isArray(recentResponses)) {
    recentResponses = [];
}


// ============================================================
// NORMALIZE TEXT
// ============================================================

function normalizeText(text) {

    return String(text || "")
        .toLowerCase()
        .replace(/[!?.,:;]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
}


// ============================================================
// CHECK SAM TTS ECHO
// ============================================================

var incomingNormalized =
    normalizeText(command);

var isEcho = false;

for (
    var r = 0;
    r < recentResponses.length;
    r++
) {

    var savedResponse =
        normalizeText(recentResponses[r]);

    if (!savedResponse) {
        continue;
    }

    if (
        incomingNormalized === savedResponse
    ) {

        isEcho = true;
        break;
    }

    if (
        incomingNormalized.length >= 6 &&
        savedResponse.indexOf(
            incomingNormalized
        ) !== -1
    ) {

        isEcho = true;
        break;
    }

    if (
        savedResponse.length >= 8 &&
        incomingNormalized.indexOf(
            savedResponse
        ) !== -1
    ) {

        isEcho = true;
        break;
    }
}



// ============================================================
// COMMON SAM TTS PHRASES
// ============================================================

var samEchoPatterns = [

    "i am sam",
    "i am sam your smart manufacturing assistant",

    "hello",
    "hello akash",
    "hello aakash",

    "i will remember your name",

    "please provide the following details",
    "which item would you like",
    "which item would you like to produce",

    "item selected",
    "what quantity should i produce",
    "quantity set to",

    "what production speed",
    "production speed set to",

    "what production date",
    "production date set to",

    "what production time",
    "production time set to",

    "the machine is currently on",
    "the machine is currently off",

    "place order or stop",
    "please say place order or stop",

    "placing the production order",

    "production order stopped",
    "production conversation reset",

    "i could not understand the quantity",
    "i could not understand the date",
    "i could not understand the time",

    "please provide a valid production speed",

    "you are welcome",
    "bye bye",

    "i did not understand that",
    "please try again"
];


for (
    var e = 0;
    e < samEchoPatterns.length;
    e++
) {

    var pattern =
        normalizeText(
            samEchoPatterns[e]
        );

    if (

        incomingNormalized === pattern ||

        (
            incomingNormalized.length >= 6 &&
            incomingNormalized.indexOf(pattern) !== -1
        ) ||

        (
            pattern.length >= 8 &&
            pattern.indexOf(incomingNormalized) !== -1
        )

    ) {

        isEcho = true;
        break;
    }
}


// ============================================================
// IMPORTANT CONTROL COMMANDS
// NEVER BLOCK AS TTS ECHO
// ============================================================

var isControlCommand =

    clean === "sam" ||

    clean === "stop" ||
    clean === "stop sam" ||
    clean === "stop voice" ||

    clean === "machine status" ||
    clean === "tell machine status" ||
    clean === "what is the machine status" ||
    clean === "machine state" ||
    clean === "status of machine" ||
    clean === "is the machine on" ||

    clean === "machine on" ||
    clean === "turn machine on" ||
    clean === "switch machine on" ||
    clean === "on machine" ||

    clean === "machine off" ||
    clean === "turn machine off" ||
    clean === "switch machine off" ||
    clean === "off machine" ||
    clean === "stop the machine" ||
    clean === "stop machine" ||

    clean === "show item list" ||
    clean === "show items" ||
    clean === "item list" ||
    clean === "show production items";


// ============================================================
// IGNORE SAM TTS ECHO
// ============================================================

if (
    isEcho &&
    !isControlCommand &&
    !isQuantityBypass
) {

    node.warn(
        "SAM IGNORE | TTS echo detected: " +
        command
    );

    return null;
}


// ============================================================
// SEND SAM RESPONSE
// ============================================================

function sendResponse(text) {

    response = text;

    var normalizedResponse =
        normalizeText(text);

    recentResponses.push(
        normalizedResponse
    );

    if (
        recentResponses.length > 8
    ) {

        recentResponses.shift();
    }

    flow.set(
        "SAM_RECENT_RESPONSES",
        recentResponses
    );

    flow.set(
        "SAM_VOICE_PAUSED",
        true
    );

    msg.payload = response;

    msg.userName = userName;

    msg.samResponse = response;

    msg.pauseVoice = true;

    return msg;
}


// ============================================================
// HELPER
// READ LIVE MACHINE STATUS
// ============================================================

function getLiveMachineStatus() {

    var samData =
        global.get("SAM_data");

    if (
        samData &&
        typeof samData.machineStatus === "boolean"
    ) {

        return samData.machineStatus;
    }

    return null;
}
// ============================================================
// START NOW - PRODUCTION WAKE COMMAND
// ============================================================
// "Start Now" = production starts automatically after 1 minute.
//
// Uses EXISTING values:
//   - Serial Number
//   - Item
//   - Quantity
//   - Production Speed
//
// Automatically sets:
//   - Date = TODAY
//   - Time = CURRENT IST TIME + 1 MINUTE
//
// Does NOT ask:
//   - Item
//   - Quantity
//   - Speed
//   - Date
//   - Time
//   - Place order or Stop?
//
// Directly sends:
//   PRODUCTION_ORDER_PLACED
// ============================================================

if (clean === "start now") {

    // ========================================================
    // READ CURRENT SAM MEMORY
    // ========================================================

    var samDataStartNow =
        global.get("SAM_data") || {};

    // ========================================================
    // READ EXISTING PRODUCTION ORDER
    // ========================================================

    var existingStartNowOrder =
        flow.get("SAM_PRODUCTION_ORDER") || {};

    // ========================================================
    // READ CURRENT SELECTED ITEM
    // ========================================================

    var selectedItem =
        flow.get("SAM_selectedItem");

    var selectedSlno =
        flow.get("SAM_selectedItemSlno");

    // ========================================================
    // FALLBACK TO EXISTING PRODUCTION ORDER
    // ========================================================

    if (
        !selectedItem &&
        existingStartNowOrder.item
    ) {
        selectedItem =
            existingStartNowOrder.item;
    }

    if (
        (selectedSlno === undefined ||
         selectedSlno === null ||
         selectedSlno === "") &&
        existingStartNowOrder.itemSlno !== undefined
    ) {
        selectedSlno =
            existingStartNowOrder.itemSlno;
    }

    // ========================================================
    // FALLBACK TO SAM MEMORY ITEM
    // ========================================================

    if (
        !selectedItem &&
        samDataStartNow.item
    ) {
        selectedItem =
            samDataStartNow.item;
    }

    // ========================================================
    // QUANTITY
    // ========================================================

    var startNowQuantity =
        samDataStartNow.setQty;

    if (
        startNowQuantity === undefined ||
        startNowQuantity === null ||
        startNowQuantity === ""
    ) {
        startNowQuantity =
            existingStartNowOrder.quantity;
    }

    // ========================================================
    // PRODUCTION SPEED
    // ========================================================

    var startNowSpeed =
        samDataStartNow.productionSpeed;

    if (
        startNowSpeed === undefined ||
        startNowSpeed === null ||
        startNowSpeed === ""
    ) {
        startNowSpeed =
            existingStartNowOrder.productionSpeed;
    }

    // ========================================================
    // FIND SERIAL NUMBER FROM AVAILABLE ITEMS
    // ========================================================

    var startNowAvailableItems =
        flow.get("availableItems");

    if (
        !Array.isArray(startNowAvailableItems)
    ) {
        startNowAvailableItems = [
            "PCB",
            "Solid Plate",
            "Round Plate"
        ];
    }

    // If selectedSlno already exists, keep it.
    // Otherwise find the item in availableItems.

    if (
        selectedSlno === undefined ||
        selectedSlno === null ||
        selectedSlno === ""
    ) {

        for (
            var si = 0;
            si < startNowAvailableItems.length;
            si++
        ) {

            var availableStartItem =
                startNowAvailableItems[si];

            var availableStartName = "";
            var availableStartSlno = si + 1;

            if (
                typeof availableStartItem === "string"
            ) {

                availableStartName =
                    availableStartItem;

            } else if (
                availableStartItem &&
                typeof availableStartItem === "object"
            ) {

                availableStartName =
                    availableStartItem.item ||
                    availableStartItem.name ||
                    availableStartItem.label ||
                    "";

                if (
                    availableStartItem.slno !== undefined
                ) {
                    availableStartSlno =
                        availableStartItem.slno;

                } else if (
                    availableStartItem.id !== undefined
                ) {
                    availableStartSlno =
                        availableStartItem.id;

                } else if (
                    availableStartItem.serial !== undefined
                ) {
                    availableStartSlno =
                        availableStartItem.serial;
                }
            }

            if (
                String(availableStartName)
                    .trim()
                    .toLowerCase() ===
                String(selectedItem || "")
                    .trim()
                    .toLowerCase()
            ) {

                selectedSlno =
                    availableStartSlno;

                break;
            }
        }
    }

    // ========================================================
    // VALIDATE EXISTING DATA
    // ========================================================

    if (
        !selectedItem ||
        selectedSlno === undefined ||
        selectedSlno === null ||
        selectedSlno === "" ||
        startNowQuantity === undefined ||
        startNowQuantity === null ||
        startNowQuantity === "" ||
        startNowSpeed === undefined ||
        startNowSpeed === null ||
        startNowSpeed === ""
    ) {

        node.warn(
            "SAM START NOW | MISSING DATA | " +
            "Item=" + selectedItem +
            " | SlNo=" + selectedSlno +
            " | Qty=" + startNowQuantity +
            " | Speed=" + startNowSpeed
        );

        sendResponse(
            "Please select an item, quantity and production speed first."
        );

        msg.samCommand = null;
        msg.machineCommand = null;
        msg.backendCommands = [];
        msg.orderPlaced = false;

        return msg;
    }

    // ========================================================
    // IST CURRENT TIME + 1 MINUTE
    // ========================================================

    var startNowTarget =
        new Date(
            Date.now() + (2*60 * 1000)
        );

    // Convert to IST safely
    var startNowIST =
        new Date(
            startNowTarget.toLocaleString(
                "en-US",
                {
                    timeZone: "Asia/Kolkata"
                }
            )
        );

    // ========================================================
    // DATE
    // ========================================================

    var startNowDay =
        startNowIST.getDate();

    var startNowMonth =
        startNowIST.getMonth() + 1;

    var startNowYear =
        startNowIST.getFullYear();

    var startNowDate =
        String(startNowDay).padStart(2, "0") +
        "/" +
        String(startNowMonth).padStart(2, "0") +
        "/" +
        String(startNowYear);

    // ========================================================
    // TIME
    // ========================================================

    var startNowHour =
        startNowIST.getHours();

    var startNowMinute =
        startNowIST.getMinutes();

    var startNowTime =
        String(startNowHour).padStart(2, "0") +
        ":" +
        String(startNowMinute).padStart(2, "0");

    // ========================================================
    // BUILD PRODUCTION ORDER
    // ========================================================

    var startNowOrder = {

        item:
            String(selectedItem).trim(),

        itemSlno:
            Number(selectedSlno),

        quantity:
            Number(startNowQuantity),

        productionSpeed:
            Number(startNowSpeed),

        productionDate:
            startNowDate,

        productionYear:
            startNowYear,

        productionDay:
            startNowDay,

        productionMonth:
            startNowMonth,

        productionTime:
            startNowTime
    };

    // ========================================================
    // SAVE ORDER
    // ========================================================

    flow.set(
        "SAM_PRODUCTION_ORDER",
        startNowOrder
    );

    // ========================================================
    // DEBUG
    // ========================================================

    node.warn(
        "SAM START NOW | AUTOMATIC ORDER | " +
        "SlNo=" + startNowOrder.itemSlno +
        " | Item=" + startNowOrder.item +
        " | Qty=" + startNowOrder.quantity +
        " | Speed=" + startNowOrder.productionSpeed +
        "% | Date=" + startNowOrder.productionDate +
        " | Time=" + startNowOrder.productionTime
    );

    // ========================================================
    // RESPONSE
    // ========================================================

    sendResponse(
        "Starting production for serial number " +
        startNowOrder.itemSlno +
        ", item " +
        startNowOrder.item +
        ", quantity " +
        startNowOrder.quantity +
        ", at speed " +
        startNowOrder.productionSpeed +
        " percent on " +
        startNowOrder.productionDate +
        " at " +
        startNowOrder.productionTime +
        "."
    );

    // ========================================================
    // DIRECT PRODUCTION ORDER
    // ========================================================

    msg.samCommand = true;

    msg.machineCommand = true;

    msg.orderPlaced = true;

    msg.backendCommands = [
        "PLACE_PRODUCTION_ORDER"
    ];

    // ========================================================
    // IMPORTANT
    // Existing production-order nodes recognize this
    // ========================================================

    msg.command =
        "PRODUCTION_ORDER_PLACED";

    // ========================================================
    // CLOSE ITEM POPUP
    // ========================================================

    msg.closeItemPopup = true;

    // ========================================================
    // END FSM CONVERSATION
    // ========================================================

    flow.set(
        "SAM_PRODUCTION_STATE",
        "NORMAL"
    );

    flow.set(
        "SAM_itemSelectionMode",
        false
    );

    flow.set(
        "SAM_itemSelectionItems",
        []
    );

    // ========================================================
    // DO NOT CLEAR SAM_PRODUCTION_ORDER
    // Downstream production nodes need it.
    // ========================================================

    flow.set(
        "SAM_PRODUCTION_ORDER",
        startNowOrder
    );

    // ========================================================
    // STOP VOICE AFTER CONFIRMATION
    // ========================================================

    flow.set(
        "SAM_VOICE_ACTIVE",
        false
    );

    flow.set(
        "SAM_VOICE_PAUSED",
        false
    );

    msg.stopVoice = true;

    // ========================================================
    // DIRECT RETURN
    // ========================================================

    return msg;
}

// ============================================================
// SAM WAKE WORD
// ============================================================

if (
    clean === "sam"
) {

    sendResponse(
        "Hello, I am SAM, your smart manufacturing assistant. Who are you?"
    );

    msg.samCommand = null;
    msg.machineCommand = null;
    msg.backendCommands = [];

    msg.stopVoice = false;
    msg.pauseVoice = true;

    return msg;
}


// ============================================================
// THANK YOU
// ============================================================

if (
    clean === "thank you" ||
    clean === "thanks" ||
    clean === "thank you sam" ||
    clean === "thanks sam"
) {

    flow.set(
        "SAM_VOICE_ACTIVE",
        false
    );

    flow.set(
        "SAM_VOICE_PAUSED",
        false
    );

    flow.set(
        "SAM_PRODUCTION_STATE",
        "NORMAL"
    );

    flow.set(
        "SAM_PRODUCTION_ORDER",
        {}
    );

    flow.set(
        "SAM_itemSelectionMode",
        false
    );

    flow.set(
        "SAM_itemSelectionItems",
        []
    );

    sendResponse(
        "You are welcome."
    );

    msg.stopVoice = true;
    msg.pauseVoice = false;

    msg.samCommand = null;
    msg.machineCommand = null;
    msg.backendCommands = [];

    msg.closeItemPopup = true;

    msg.command =
        "STOP_VOICE";

    return msg;
}

// ========================================================
// SHUTDOWN PRODUCTION
// ========================================================
// Normal command only.
// Does NOT affect production-order sequence.
// ========================================================

let shutdownProduction =
    /\bshutdown\s+production\b/i.test(
        String(msg.payload || "").trim()
    );

if (shutdownProduction) {

    msg.topic = "Shutdown Production";
    msg.payload = false;

    node.warn(
        "SAM COMMAND | Shutdown Production | false"
    );

    return msg;
}
// ============================================================
// MACHINE STATUS
// ============================================================

if (
    clean === "machine status" ||
    clean === "tell machine status" ||
    clean === "what is the machine status" ||
    clean === "machine state" ||
    clean === "status of machine" ||
    clean === "is the machine on" ||
    clean === "is the machine off" ||
    clean === "is machine on" ||
    clean === "is machine off" ||
    clean === "what is current machine status" ||
    clean === "what is the current machine status"
) {

    var liveMachineStatus =
        getLiveMachineStatus();

    if (
        liveMachineStatus === true
    ) {

        sendResponse(
            "The machine is currently ON."
        );
    }

    else if (
        liveMachineStatus === false
    ) {

        sendResponse(
            "The machine is currently shutdown"
        );
    }

    else {

        sendResponse(
            "I could not determine the machine status. Please check the machine."
        );

        node.warn(
            "SAM MACHINE STATUS | global.SAM_data.machineStatus unavailable"
        );
    }

    msg.samCommand = null;
    msg.machineCommand = null;
    msg.backendCommands = [];
    msg.stopVoice = false;
    msg.orderPlaced = false;
    msg.suppressResponse = false;

    return msg;
}


// ============================================================
// MACHINE ON
// ============================================================

if (
    clean === "machine on" ||
    clean === "turn machine on" ||
    clean === "switch machine on" ||
    clean === "on machine"
) {

    msg.samCommand = true;

    // PLC command must be sent
    msg.machineCommand = true;

    msg.suppressResponse = true;

    msg.backendCommands = [
        "MACHINE_ON"
    ];

    if (
        state === "WAITING_MACHINE_ON"
    ) {

        flow.set(
            "SAM_PRODUCTION_STATE",
            "WAITING_PLACE_ORDER"
        );

        node.warn(
            "SAM MACHINE ON | Production sequence -> WAITING_PLACE_ORDER"
        );
    }

    else {

        flow.set(
            "SAM_PRODUCTION_STATE",
            state
        );

        node.warn(
            "SAM MACHINE ON | Production state preserved: " +
            state
        );
    }

    node.warn(
        "SAM MACHINE COMMAND | ON | samCommand=true"
    );

    return msg;
}


// ============================================================
// MACHINE OFF
// ============================================================

if (
    clean === "machine off" ||
    clean === "turn machine off" ||
    clean === "switch machine off" ||
    clean === "off machine" ||
    clean === "stop the machine" ||
    clean === "stop machine"
) {

    // PLC needs false
    msg.samCommand = false;

    // Keep machineCommand true so PLC node processes command
    msg.machineCommand = true;

    msg.suppressResponse = true;

    msg.backendCommands = [
        "MACHINE_OFF"
    ];

    flow.set(
        "SAM_PRODUCTION_STATE",
        state
    );

    node.warn(
        "SAM MACHINE COMMAND | OFF | samCommand=false"
    );

    node.warn(
