var TIME_WORD_TO_NUM = {
    one: 1, two: 2, three: 3, four: 4, five: 5, six: 6,
    seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12
};

function parseSpokenTime(text) {

    var t = String(text || "");

    Object.keys(TIME_WORD_TO_NUM).forEach(function(w) {
        var re = new RegExp("\\b" + w + "\\b", "g");
        t = t.replace(re, TIME_WORD_TO_NUM[w]);
    });

    var m = t.match(/\b(\d{1,2})(?::|\.|\s)(\d{1,2})\s*(am|pm|a m|p m)?\b/);
    if (m) {
        return { hour: Number(m[1]), minute: Number(m[2]), ampm: (m[3] || "").replace(/\s/g, "") };
    }

    m = t.match(/\b(\d{3,4})\s*(am|pm|a m|p m)?\b/);
    if (m) {
        var digits = m[1];
        var hh = digits.length === 3 ? digits.slice(0, 1) : digits.slice(0, 2);
        var mm = digits.length === 3 ? digits.slice(1) : digits.slice(2);
        return { hour: Number(hh), minute: Number(mm), ampm: (m[2] || "").replace(/\s/g, "") };
    }

    m = t.match(/\b(\d{1,2})\s*(am|pm|a m|p m)\b/);
    if (m) {
        return { hour: Number(m[1]), minute: 0, ampm: m[2].replace(/\s/g, "") };
    }

    return null;
}
    if (
