// ============================================================
// NUMBER PARSER
// ============================================================

function parseSpokenNumber(value) {

    value = value
        .toLowerCase()
        .trim()
        .replace(/-/g, " ");


    // Direct number
    if (/^\d+(\.\d+)?$/.test(value)) {

        let n = Number(value);

        if (Number.isFinite(n)) {
            return n;
        }

        return null;
    }


    const ones = {
        zero: 0,
        one: 1,
        two: 2,
        three: 3,
        four: 4,
        five: 5,
        six: 6,
        seven: 7,
        eight: 8,
        nine: 9,
        ten: 10,
        eleven: 11,
        twelve: 12,
        thirteen: 13,
        fourteen: 14,
        fifteen: 15,
        sixteen: 16,
        seventeen: 17,
        eighteen: 18,
        nineteen: 19
    };


    const tens = {
        twenty: 20,
        thirty: 30,
        forty: 40,
        fifty: 50,
        sixty: 60,
        seventy: 70,
        eighty: 80,
        ninety: 90
    };


    let words = value
        .split(/\s+/)
        .filter(Boolean);


    words = words.filter(function(word) {

        return (
            word !== "percent" &&
            word !== "percentage" &&
            word !== "%"
        );

    });


    if (words.length === 0) {
        return null;
    }


    // Single word
    if (words.length === 1) {

        if (ones.hasOwnProperty(words[0])) {
            return ones[words[0]];
        }

        if (tens.hasOwnProperty(words[0])) {
            return tens[words[0]];
        }

        return null;
    }


    // Multiple words
    let current = 0;

    for (let i = 0; i < words.length; i++) {

        let word = words[i];


        if (ones.hasOwnProperty(word)) {

            current += ones[word];

            continue;
        }


        if (tens.hasOwnProperty(word)) {

            current += tens[word];

            continue;
        }


        if (word === "hundred") {

            if (current === 0) {
                current = 1;
            }

            current *= 100;

            continue;
        }


        if (word === "and") {
            continue;
        }


        return null;
    }


    return current;
}


