// ============================================================

const gripperWord =
    "(?:gripper|greeper|griper|grippper|grippa|grip|creeper)";


// ============================================================
// PERCENTAGE REQUEST
// ============================================================
//
// percent
// percentage
// %
// gripper percent
// gripper percentage
// gripper %
// ============================================================

const percentageRequestRegex =
    new RegExp(
        "^\\s*(?:the\\s+)?" +
        "(?:" + gripperWord + "\\s+)?" +
        "(?:percent|percentage|%)" +
        "\\s*$",
        "i"
    );


if (percentageRequestRegex.test(text)) {

    context.set(
        "waitingForGripperPercent",
        true
    );

    node.warn(
        "WAITING FOR GRIPPER PERCENTAGE"
    );


    return samResponse(
        "Please say the gripper percentage."
    );
}


// ============================================================
// WAITING FOR GRIPPER PERCENTAGE
// ============================================================

if (waitingForGripperPercent) {

    let numberValue =
        parseSpokenNumber(text);


    if (
        numberValue !== null &&
        Number.isFinite(numberValue) &&
        numberValue >= 1 &&
        numberValue <= 100
    ) {

        numberValue =
            Math.round(numberValue);


        context.set(
            "waitingForGripperPercent",
            false
        );


        node.warn(
            "GRIPPER PERCENTAGE: " +
            numberValue
        );


        return [
            {
                topic: "gripper%",
                payload: numberValue
            },
            null
        ];
    }


    return samResponse(
        "Please say a gripper percentage between 1 and 100."
    );
}


// ============================================================
// DIRECT GRIPPER PERCENTAGE
// ============================================================
//
// gripper 50
// gripper 50 percent
// gripper fifty
// gripper fifty percent
// grip 20
// greeper 80 percentage
// ============================================================

const directPercentRegex =
    new RegExp(
        "^\\s*" +
        "(?:(?:set|make)\\s+)?" +
        gripperWord +
        "\\s+" +
        "(.+?)" +
        "\\s*(?:percent|percentage|%)?" +
        "\\s*$",
        "i"
    );


let directPercentMatch =
    text.match(directPercentRegex);


if (
    directPercentMatch &&
    (
        /\bpercent\b/i.test(text) ||
        /\bpercentage\b/i.test(text) ||
        /%/.test(text) ||
        /^(?:gripper|greeper|griper|grippper|grippa|grip)\s+\d+/i.test(text)
    )
) {

    let numberText =
        directPercentMatch[1]
            .replace(/\bpercent\b/gi, "")
            .replace(/\bpercentage\b/gi, "")
            .replace(/%/g, "")
            .trim();


    let numberValue =
        parseSpokenNumber(numberText);


    if (
        numberValue !== null &&
        Number.isFinite(numberValue) &&
        numberValue >= 1 &&
        numberValue <= 100
    ) {

        numberValue =
            Math.round(numberValue);


        node.warn(
            "DIRECT GRIPPER PERCENTAGE: " +
            numberValue
        );


        return [
            {
                topic: "gripper",
                payload: numberValue
            },
            null
        ];
    }
}


